import LiquidGlass
import Observation
import SwiftUI

/// The shared wallpapers (generated by assets/wallpapers/generate.swift).
enum Wallpaper: String, CaseIterable, Identifiable {
    case aurora, dunes, ocean, midnight

    var id: String { rawValue }
    var title: String { rawValue.capitalized }

    /// The wallpaper filling the space it is offered.
    var view: some View {
        Image(rawValue)
            .resizable()
            .scaledToFill()
            .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity)
            .clipped()
            .accessibilityHidden(true)
    }
}

/// The Materials lab's live options.
@Observable
final class LabSettings {
    var material = GlassMaterial.clear
    var appearance = GlassAppearance.automatic
    var refraction = 60.0
    var radius = 48.0
    var capsule = false
    var tint: LabTint = .none
    var wallpaper = Wallpaper.dunes

    var glassRadius: GlassRadius { capsule ? .capsule : .points(radius) }
}

/// Tints the lab offers, from the system palette.
enum LabTint: String, CaseIterable, Identifiable {
    case none, blue, purple, pink, orange, green

    var id: String { rawValue }

    var color: Color? {
        switch self {
        case .none: nil
        case .blue: Color(red: 0, green: 0.478, blue: 1)
        case .purple: Color(red: 0.686, green: 0.322, blue: 0.871)
        case .pink: Color(red: 1, green: 0.176, blue: 0.333)
        case .orange: Color(red: 1, green: 0.584, blue: 0)
        case .green: Color(red: 0.204, green: 0.780, blue: 0.349)
        }
    }
}

/// A section heading drawn straight on a wallpaper.
struct SectionHeader: View {
    let title: String

    var body: some View {
        Text(title)
            .font(.footnote.weight(.semibold))
            .textCase(.uppercase)
            .kerning(0.6)
            .foregroundStyle(.white.opacity(0.9))
            .shadow(color: .black.opacity(0.25), radius: 4, y: 1)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, 4)
            .accessibilityAddTraits(.isHeader)
    }
}

/// Room for the floating tab bar at the bottom of every page.
enum StudioLayout {
    #if os(macOS)
    static let tabBarClearance: CGFloat = 72
    static let pagePadding: CGFloat = 32
    #else
    static let tabBarClearance: CGFloat = 84
    static let pagePadding: CGFloat = 20
    #endif
}
